mapper.update:
update campus_order
status = #{status}, receiver_name = #{receiverName}, receiver_phone = #{receiverPhone}, address = #{address}, remark = #{remark}, pay_time = #{payTime}, ship_time = #{shipTime}, logistics_no = #{logisticsNo}, finish_time = #{finishTime}, cancel_time = #{cancelTime},
where id = #{id}

mapper.select:
select  from campus_order

    and user_id = #{userId}
    and status = #{status}
    and order_no like concat('%', #{orderNo}, '%')

order by create_time desc

select  from campus_order
where status = 0 and create_time < #{deadline}
order by create_time asc
